# Rule candidate: holes->2; span line on marker side covering hole-range (full if single); connector from each hole into interior (away from marker edge) while free.
def solve(g,vert):
    h=len(g); w=len(g[0])
    mk=[(r,c) for r in range(h) for c in range(w) if g[r][c]==2][0]
    out=[row[:] for row in g]
    bands = [b for b in range(h)] if vert else [b for b in range(w)]
    # vertical case: bands are columns; horizontal shift direction toward interior (right if marker left)
    if not vert:
        d=(0,1) if mk[1]==0 else (0,-1)
        def cell(r,c): return 0<=r<h and 0<=c<w
        for b in bands:
            holes=[r for r in range(h) if g[r][b]==0 and r!=mk[0]]
            for r in holes:
                out[r][b]=2
            lo,hi=min(holes),max(holes)
            if len(holes)==1: rng=list(range(h))
            else: rng=list(range(lo,hi+1))
            sgn=-1 if d==(-1,0) or d==(0,-1) else 1
            for r in rng:
                c=b+sgn
                while cell(r,c) and g[r][c]==0:
                    out[r][c]=2; c+=sgn
        for b in bands:
            holes=[r for r in range(h) if g[r][b]==0 and r!=mk[0]]
            for r in holes:
                c=b+d[1]
                while cell(r,c) and g[r][c]==0:
                    out[r][c]=2; c+=d[1]
    else:
        dirs=[(-1,0),(1,0)]
        d=dirs[0] if mk[0]==0 else dirs[1]
        sgn=-1 if d[0]<0 else 1
        for b in bands:
            holes=[c for c in range(w) if g[b][c]==0 and c!=mk[1]]
            for c in holes:
                out[b][c]=2
            lo,hi=min(holes),max(holes)
            if len(holes)==1: rng=list(range(w))
            else: rng=list(range(lo,hi+1))
            rr=b+sgn
            while 0<=rr<h and g[rr][c]==0:
                out[rr][c]=2; rr+=sgn
        for b in bands:
            holes=[c for c in range(w) if g[b][c]==0 and c!=mk[1]]
            for c in holes:
                r=b+d[0]
                while 0<=r<h and g[r][c]==0:
                    out[r][c]=2; r+=d[0]
    return out
def f(g):
    n_rows=sum(1 for r in range(len(g)) if 8 in g[r])
    n_cols=sum(1 for c in range(len(g[0])) if any(g[r][c]==8 for r in range(len(g))))
    return solve(g,n_rows<=n_cols)
