def bfs(src, inp, h, w):
    dist={}
    q=collections.deque([(src[0],src[1],0)])
    dist[(src[0],src[1])]=0
    while q:
        r,c,d=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and inp[nr][nc]!=8 and (nr,nc) not in dist:
                dist[(nr,nc)]=d+1; q.append((nr,nc))
    return dist
