import collections
def bfs(src, inp):
    h=len(inp);w=len(inp[0])
    dist={src:0}
    q=collections.deque([src])
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and (nr,nc) not in dist and inp[nr][nc]!=8:
                dist[(nr,nc)]=dist[(r,c)]+1; q.append((nr,nc))
    return dist
