    Cs.insert(0,[seedcells[0]])
    used=[]
    remaining=list(Cs)
    while len(remaining)>1:
        best=min(((mindist(a,b),i,j) for i,a in enumerate(remaining) for j,b in enumerate(remaining) if i<j))
        _,i,j=best
        used.append((i,j))
        rem=[k for k in remaining if k not in (i,j)]
        # merge: union cells of the two comps
        remaining=rem+[remaining[i]+remaining[j]]
    print(n,'ncomps',len(Cs),'merged pairs:',used)

